repo.tickets.py:
"""Ticket records."""


class Ticket:
    def __init__(self, team, hours):
        self.team = team
        self.hours = hours

    def __repr__(self):
        return "Ticket(%r, %r)" % (self.team, self.hours)


ROWS = [('ops', 39), ('data', 34), ('data', 49), ('web', 6), ('data', 22), ('data', 11), ('ops', 56)]


def load_tickets():
    """Yield the stored tickets one at a time."""
    for team, hours in ROWS:
        yield Ticket(team, hours)

repo.ranges.py:
"""Position windows over tickets."""


def hours_between(tickets, low, high):
    """Return the hours of the tickets at positions low to high, both included. Positions start at 1."""
    return [x.hours for x in tickets[low - 1:high - 1]]


def first_hourss(tickets, n):
    """Return the hours of the first n tickets."""
    return hours_between(tickets, 1, n)


def group_by_team(tickets):
    """Return a dict from team to the list of tickets with that team."""
    groups = {}
    for x in tickets:
        groups.setdefault(x.team, []).append(x)
    return groups

